    public static let dark = ManicatTokens(
        background: Color(hex: "#141414"), surface: Color(hex: "#191919"), surfaceRaised: Color(hex: "#1f1f1f"), surfaceMuted: Color(hex: "#242424"),
        foreground: Color(hex: "#f2f2f2"), textSecondary: Color(hex: "#b4b4b4"), textMuted: Color(hex: "#8c8c8c"),
        border: Color(hex: "#2b2b2b"), borderSubtle: Color(hex: "#222222"), borderStrong: Color(hex: "#484848"),
        accent: Color(hex: "#bebebe"), accentStrong: Color(hex: "#e1e1e1"), accentSubtle: Color(hex: "#bebebe", opacity: 0.13), accentForeground: Color(hex: "#141414"),
